"use client";
import type { ButtonHTMLAttributes } from "react";
import { useDecode } from "./ascii-decode";
import "./ascii-decode.css";
import "./scramble-button.css";

export function ScrambleButton({
  children,
  className = "",
  type = "button",
  ...props
}: Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> & {
  children: string;
}) {
  const [shown, run] = useDecode(children, 520);
  return (
    <button
      {...props}
      type={type}
      className={`forme-scramble ${className}`}
      onPointerEnter={(e) => {
        run();
        props.onPointerEnter?.(e);
      }}
      onFocus={(e) => {
        run();
        props.onFocus?.(e);
      }}
    >
      <span className="forme-decode">
        <span className="forme-decode-final">{children}</span>
        <span className="forme-decode-live" aria-hidden="true">
          {shown}
        </span>
      </span>
    </button>
  );
}

.forme-scramble {
  display: inline-flex;
  align-items: center;
  height: 48px;
  padding: 0 26px;
  border: 1px solid #ffffff24;
  border-radius: 999px;
  background: transparent;
  color: #ededf0;
  font: inherit;
  font-size: 15px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition:
    background 0.25s,
    border-color 0.25s,
    transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.forme-scramble:hover,
.forme-scramble:focus-visible {
  background: #ffffff0d;
  border-color: #ffffff40;
}
.forme-scramble:active {
  transform: scale(0.98);
}
.forme-scramble:focus-visible {
  outline: 2px solid #ededf0;
  outline-offset: 3px;
}
.forme-scramble:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
@media (prefers-reduced-motion: reduce) {
  .forme-scramble {
    transition: none;
  }
  .forme-scramble:active {
    transform: none;
  }
}

"use client";
import { createElement, useCallback, useEffect, useRef, useState } from "react";
import "./ascii-decode.css";

const glyphs = "!<>-_/[]{}=+*^?#%@01ABCDEFXZ";
/** Returns the visible text and a function that decodes it from noise. */
export function useDecode(text: string, duration = 900) {
  const [shown, setShown] = useState(text);
  const frame = useRef(0);
  const run = useCallback(() => {
    cancelAnimationFrame(frame.current);
    if (matchMedia("(prefers-reduced-motion:reduce)").matches)
      return setShown(text);
    const start = performance.now();
    let step = -1;
    const tick = (now: number) => {
      const progress = Math.min(1, (now - start) / duration);
      // New noise every 45 ms reads as decoding instead of flicker.
      if (Math.floor((now - start) / 45) !== step || progress === 1) {
        step = Math.floor((now - start) / 45);
        const solved = progress * text.length;
        setShown(
          Array.from(text, (ch, i) =>
            i < solved || ch === " "
              ? ch
              : glyphs[Math.floor(Math.random() * glyphs.length)],
          ).join(""),
        );
      }
      if (progress < 1) frame.current = requestAnimationFrame(tick);
    };
    frame.current = requestAnimationFrame(tick);
  }, [text, duration]);
  useEffect(() => {
    setShown(text);
    return () => cancelAnimationFrame(frame.current);
  }, [text]);
  return [shown, run] as const;
}

export function AsciiDecode({
  text,
  as = "span",
  className = "",
  duration = 900,
  replayOnHover = true,
}: {
  text: string;
  as?: "span" | "h1" | "h2" | "h3" | "p";
  className?: string;
  duration?: number;
  replayOnHover?: boolean;
}) {
  const ref = useRef<HTMLElement>(null);
  const [shown, run] = useDecode(text, duration);
  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => {
      if (!entry.isIntersecting) return;
      run();
      observer.disconnect();
    });
    observer.observe(ref.current!);
    return () => observer.disconnect();
  }, [run]);
  return createElement(
    as,
    {
      ref,
      className: `forme-decode ${className}`,
      onPointerEnter: replayOnHover ? run : undefined,
    },
    <span className="forme-decode-final">{text}</span>,
    <span className="forme-decode-live" aria-hidden="true">
      {shown}
    </span>,
  );
}

.forme-decode {
  position: relative;
}
span.forme-decode {
  display: inline-block;
}
/* The real text holds layout and stays readable to assistive technology. */
.forme-decode-final {
  color: transparent;
}
.forme-decode-live {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
